(3658968, 510740, 5792, '<td valign="top">Nice water motion shot. Meets challenge well. Blue color cast overdone, slightly oversharpened tops of the rocks. Horizon may be slightly tilted clockwise about a degree.</td>', 'Nice water motion shot. Meets challenge well. Blue color cast overdone, slightly oversharpened tops of the rocks. Horizon may be slightly tilted clockwise about a degree.', '2007-05-17 03:20:36.000000', NULL, 1),
(3658984, 510566, 5792, '<td valign="top">Shallow depth of field(DOF) leaves front out of focus, try shooting at a higher f/stop number for increased DOF.</td>', 'Shallow depth of field(DOF) leaves front out of focus, try shooting at a higher f/stop number for increased DOF.', '2007-05-17 03:26:17.000000', NULL, 1),
(3659062, 512886, 5792, '<td valign="top">Very well processed image. We had the same idea and similar problems. Like me, you had problems with wind that moved some branches during the exposure and you added a blue color cast, possibly while adjusting for deep greens. You went for maximum depth of field with nice sharp foreground interest items just like I did. I was unsatisfied with my processing after a second re-processing so did not submit.</td>', 'Very well processed image. We had the same idea and similar problems. Like me, you had problems with wind that moved some branches during the exposure and you added a blue color cast, possibly while adjusting for deep greens. You went for maximum depth of field with nice sharp foreground interest items just like I did. I was unsatisfied with my processing after a second re-processing so did not submit.', '2007-05-17 04:11:15.000000', NULL, 1),
(3659069, 512900, 5792, '<td valign="top">Likely a top 10 image with top 5 potential and an outside chance for a ribbon because of its strong connection to the challenge theme. :)</td>', 'Likely a top 10 image with top 5 potential and an outside chance for a ribbon because of its strong connection to the challenge theme. :)', '2007-05-17 04:27:38.000000', NULL, 1),
