(3670124, 512441, 53690, '<td valign="top">Gorgeous, radiant colors here.  The reflection in the droplet is amazing, and the crispness blows me away.  10 from me!</td>', 'Gorgeous, radiant colors here.  The reflection in the droplet is amazing, and the crispness blows me away.  10 from me!', '2007-05-20 19:39:23.000000', NULL, 1),
