INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3680108, 511222, 30049, '<td valign="top">Have the postcard/greeting card companies come calling yet?!  Very well seen and captured.  Great control of lighting and composition.  The only thing holding this back at all (I still gave it a top score) is I wish for a little more room up top and more size overall (you''re 640 on the top/btm, but only 331 on the sides).  Best of luck to you in the challenge.</td>', 'Have the postcard/greeting card companies come calling yet?!  Very well seen and captured.  Great control of lighting and composition.  The only thing holding this back at all (I still gave it a top score) is I wish for a little more room up top and more size overall (you''re 640 on the top/btm, but only 331 on the sides).  Best of luck to you in the challenge.', '2007-05-22 14:59:59.000000', NULL, 1),
(3680111, 512900, 74747, '<td valign="top">Now that''s silky!</td>', 'Now that''s silky!', '2007-05-22 15:00:21.000000', NULL, 1),
(3680116, 511954, 74747, '<td valign="top">Yum! This could be an advertisement!</td>', 'Yum! This could be an advertisement!', '2007-05-22 15:00:59.000000', NULL, 1),
(3680125, 511312, 30049, '<td valign="top">Works very well for me.  I like it.  Simple composition.  Nice use of DOF.  Well focused but not oversharpened.  The blurred lines of the background add a nice element to this, yet I keep coming back to the featured subject after roaming.  Well done.  Good luck in the challenge.</td>', 'Works very well for me.  I like it.  Simple composition.  Nice use of DOF.  Well focused but not oversharpened.  The blurred lines of the background add a nice element to this, yet I keep coming back to the featured subject after roaming.  Well done.  Good luck in the challenge.', '2007-05-22 15:02:12.000000', NULL, 1),
(3680132, 511756, 74747, '<td valign="top">WOW! Love the color in this one! Nice job.</td>', 'WOW! Love the color in this one! Nice job.', '2007-05-22 15:04:11.000000', NULL, 1),
(3680156, 511536, 30049, '<td valign="top">This is so well done I can almost feel the soft smooth silkly flower petals!  Nice.  Only minor issue is I''m seeing a midnight blue color around the outside.  Not sure if a small levels adjustment would remove that or not.<br/> <br/>Nonetheless - Well done!  Good luck.</td>', 'This is so well done I can almost feel the soft smooth silkly flower petals!  Nice.  Only minor issue is I''m seeing a midnight blue color around the outside.  Not sure if a small levels adjustment would remove that or not. Nonetheless - Well done!  Good luck.', '2007-05-22 15:07:43.000000', NULL, 1),
(3680172, 510740, 30049, '<td valign="top">Very nice use of a long shutter speed.  At first I wasn''t sure about the blue tone, but after looking a bit more (and wondering about options) I think blue works well for a soothing, relaxing feel for this photo.  Nicely done!  Good luck in the challenge.</td>', 'Very nice use of a long shutter speed.  At first I wasn''t sure about the blue tone, but after looking a bit more (and wondering about options) I think blue works well for a soothing, relaxing feel for this photo.  Nicely done!  Good luck in the challenge.', '2007-05-22 15:09:39.000000', NULL, 1),
(3680182, 512108, 30049, '<td valign="top">Sorry, but I find this pose nearly pornographic in nature and not something I feel is suitable for DPC.  JMO of course.</td>', 'Sorry, but I find this pose nearly pornographic in nature and not something I feel is suitable for DPC.  JMO of course.', '2007-05-22 15:11:30.000000', NULL, 1),
(3680189, 511756, 30049, '<td valign="top">This is quite close to being good.  I like the color.  Something about the lighting I think is holding it back and it''s not quite sharp enough IMO.  Right idea...just missed by a smidgen.  :)</td>', 'This is quite close to being good.  I like the color.  Something about the lighting I think is holding it back and it''s not quite sharp enough IMO.  Right idea...just missed by a smidgen.  :)', '2007-05-22 15:12:49.000000', NULL, 1),
(3680203, 511161, 30049, '<td valign="top">Neat idea.  Needs some attention to lighting and color balance.  Looks like you had a mixed lighting environment?  Warm on the left, cool blue on the right.  Last thing (sorry, attention to details usually scores higher), the speck of ? on the spoon needs to go.  :)</td>', 'Neat idea.  Needs some attention to lighting and color balance.  Looks like you had a mixed lighting environment?  Warm on the left, cool blue on the right.  Last thing (sorry, attention to details usually scores higher), the speck of ? on the spoon needs to go.  :)', '2007-05-22 15:15:16.000000', NULL, 1),
(3680211, 512509, 76184, '<td valign="top">The flash is a photo killer.</td>', 'The flash is a photo killer.', '2007-05-22 15:16:59.000000', NULL, 1),
(3680213, 512827, 30049, '<td valign="top">Lovely color, and the foreground bokeh adds a nice natural frame.  Shot thru some leaves at the edge of the water?  Nicely seen and captured.  Unique too!  :)  Good luck in the challenge.</td>', 'Lovely color, and the foreground bokeh adds a nice natural frame.  Shot thru some leaves at the edge of the water?  Nicely seen and captured.  Unique too!  :)  Good luck in the challenge.', '2007-05-22 15:17:19.000000', NULL, 1),
