(3685126, 509937, 42100, '<td valign="top">Most interesting smoke trails...and yes, very silky-smooth.  Congratulation on winning the <strike>yellow</strike> <i>red</i> ribbon!<br/><br/><i>Message edited by author 2007-05-23 15:25:25.</i></td>', 'Most interesting smoke trails...and yes, very silky-smooth.  Congratulation on winning the yellow red ribbon!', '2007-05-23 10:23:18.000000', '2007-05-23 16:25:25.000000', 0),
(3685135, 512197, 42100, '<td valign="top">Very nice photo...congratulations on <strike>the HM</strike> <i>winning the yellow ribbon</i>!<br/><br/><i>Message edited by author 2007-05-23 15:27:29.</i></td>', 'Very nice photo...congratulations on the HM winning the yellow ribbon!', '2007-05-23 10:24:24.000000', '2007-05-23 16:27:29.000000', 0),
